// EmergencyHelp page component
import React from "react";
import "../styles/emergency.css";

function EmergencyHelp() {

  return (
    <div className="emergency-container">

      <h1>Emergency Legal Help</h1>

      <div className="emergency-cards">

        <div className="card">
          <h2>Police Emergency</h2>
          <p>Dial: 15</p>
        </div>

        <div className="card">
          <h2>Women Helpline</h2>
          <p>Dial: 1099</p>
        </div>

        <div className="card">
          <h2>Legal Aid Helpline</h2>
          <p>Dial: 0800-70606</p>
        </div>

        <div className="card">
          <h2>Ambulance</h2>
          <p>Dial: 1122</p>
        </div>

      </div>

    </div>
  );
}

export default EmergencyHelp;
